// The snippet ex7 asks you to predict. The gate runs it from inside a timer
// callback and compares the labels with your answer. Do not edit this file.

export function run(log: (label: string) => void): void {
  Promise.resolve()
    .then(() => log("p1"))
    .then(() => log("p2"))
    .then(() => log("p3"));

  queueMicrotask(() => log("q1"));
  queueMicrotask(() => log("q2"));

  const job = async (): Promise<void> => {
    log("a-start");
    await Promise.resolve();
    log("a-1");
    await Promise.resolve();
    log("a-2");
  };
  void job();

  log("sync");
}
